49	import org.springframework.web.bind.WebDataBinder;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.InitBinder;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final OwnerFieldsValidator ownerFieldsValidator;
76	
77	    private final TelephoneNormalizer telephoneNormalizer;
78	
79	    private final EmailNormalizer emailNormalizer;
80	
81	    private final AddressNormalizer addressNormalizer;
82	
83	    private final HouseholdDuplicateValidator householdDuplicateValidator;
84	
85	    private final HouseholdAssigner householdAssigner;
86	
87	    private final CityCapacityValidator cityCapacityValidator;
88	
89	    private final DailyRegistrationLimitValidator dailyRegistrationLimitValidator;
90	
91	    public OwnerRestControllerV1(ClinicService clinicService,
92	                                 OwnerMapper ownerMapper,
93	                                 PetMapper petMapper,
94	                                 VisitMapper visitMapper,
95	                                 OwnerFieldsValidator ownerFieldsValidator,
96	                                 TelephoneNormalizer telephoneNormalizer,
97	                                 EmailNormalizer emailNormalizer,
98	                                 AddressNormalizer addressNormalizer,
99	                                 HouseholdDuplicateValidator householdDuplicateValidator,
100	                                 HouseholdAssigner householdAssigner,
101	                                 CityCapacityValidator cityCapacityValidator,
102	                                 DailyRegistrationLimitValidator dailyRegistrationLimitValidator) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	        this.ownerFieldsValidator = ownerFieldsValidator;
108	        this.telephoneNormalizer = telephoneNormalizer;
109	        this.emailNormalizer = emailNormalizer;
110	        this.addressNormalizer = addressNormalizer;
111	        this.householdDuplicateValidator = householdDuplicateValidator;
112	        this.householdAssigner = householdAssigner;
113	        this.cityCapacityValidator = cityCapacityValidator;
114	        this.dailyRegistrationLimitValidator = dailyRegistrationLimitValidator;
115	    }
116	
117	    /**
118	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
119	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
120	     */
121	    @InitBinder("ownerFieldsDto")
122	    void initOwnerFieldsBinder(WebDataBinder binder) {
123	        binder.addValidators(ownerFieldsValidator);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
129	        Collection<Owner> owners;
130	        if (lastName != null) {
131	            owners = this.clinicService.findOwnerByLastName(lastName);
132	        } else {
133	            owners = this.clinicService.findAllOwners();
134	        }
135	        if (owners.isEmpty()) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
154	        HttpHeaders headers = new HttpHeaders();
155	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
156	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
157	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
158	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
159	            throw new DuplicateTelephoneException(telephone);
160	        }
161	        dailyRegistrationLimitValidator.validate();
162	        cityCapacityValidator.validate(owner);
163	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
164	            householdAssigner.assignSharedHousehold(owner);
165	        } else {
166	            householdDuplicateValidator.validate(owner);
167	        }
168	        owner.setTelephone(telephone);
169	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
170	        this.clinicService.saveOwner(owner);
171	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
180	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
181	        if (currentOwner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        currentOwner.setAddress(ownerFieldsDto.getAddress());
185	        currentOwner.setCity(ownerFieldsDto.getCity());
186	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
187	        currentOwner.setLastName(ownerFieldsDto.getLastName());
188	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
189	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
190	        this.clinicService.saveOwner(currentOwner);
191	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Transactional
196	    @Override
197	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        this.clinicService.deleteOwner(owner);
203	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner == null) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        HttpHeaders headers = new HttpHeaders();
214	        Pet pet = petMapper.toPet(petFieldsDto);
215	        owner.setId(ownerId);
216	        pet.setOwner(owner);
217	        pet.getType().setName(null);
218	        this.clinicService.savePet(pet);
219	        PetDto petDto = petMapper.toPetDto(pet);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
221	            .buildAndExpand(pet.getId()).toUri());
222	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
223	    }
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
228	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
229	        if (currentOwner != null) {
230	            Pet currentPet = this.clinicService.findPetById(petId);
231	            if (currentPet != null) {
232	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
233	                currentPet.setName(petFieldsDto.getName());
234	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
235	                this.clinicService.savePet(currentPet);
236	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
